import { RegisterUserUseCase } from './RegisterUserUseCase';
import { UserRepository } from './UserRepository';
import { User } from './User';
import { EmailAlreadyExistsError } from './errors/EmailAlreadyExistsError';
import { Result } from './Result';

// Mock repository implementation
class MockUserRepository implements UserRepository {
  private users: User[] = [];

  async findByEmail(email: string): Promise<User | null> {
    return this.users.find(user => user.email === email) || null;
  }

  async save(user: User): Promise<void> {
    this.users.push(user);
  }
}

describe('RegisterUserUseCase', () => {
  // Arrange
  const mockRepository = new MockUserRepository();
  const registerUserUseCase = new RegisterUserUseCase(mockRepository);

  const existingUser = new User({
    id: '1',
    name: 'John Doe',
    email: 'john@example.com',
    password: 'password123'
  });

  beforeEach(() => {
    // Clear repository state before each test
    (mockRepository as any).users = [];
    // Add existing user to simulate email conflict
    mockRepository.save(existingUser);
  });

  it('should return EmailAlreadyExistsError when user email already exists', async () => {
    // Arrange
    const userInput = {
      name: 'Jane Smith',
      email: 'john@example.com', // Same email as existing user
      password: 'newpassword456'
    };

    // Act
    const result = await registerUserUseCase.execute(userInput);

    // Assert
    expect(result.isFailure()).toBe(true);
    expect(result.error).toBeInstanceOf(EmailAlreadyExistsError);
    expect(result.error.message).toBe('Email already exists');

    // Verify no new user was saved
    const users = await mockRepository.findByEmail(userInput.email);
    expect(users).toBeNull();
  });
});
