// Domain/ValueObjects/Money.spec.ts

import { Money } from "./Money";
import { describe, it, expect } from "vitest";

describe("Money", () => {
  const USD: Currency = {
    code: "USD",
    symbol: "$",
    decimalPlaces: 2
  };

  const EUR: Currency = {
    code: "EUR",
    symbol: "€",
    decimalPlaces: 2
  };

  it("should create a valid money instance", () => {
    const money = Money.create(100, USD);
    expect(money.amount).toBe(100);
    expect(money.currency).toBe(USD);
  });

  it("should throw an error when creating money with negative amount", () => {
    expect(() => Money.create(-100, USD)).toThrow("Money amount must be positive");
  });

  it("should add money with same currency", () => {
    const money1 = Money.create(100, USD);
    const money2 = Money.create(50, USD);
    const result = money1.add(money2);

    expect(result.amount).toBe(150);
    expect(result.currency).toBe(USD);
  });

  it("should throw an error when adding money with different currencies", () => {
    const money1 = Money.create(100, USD);
    const money2 = Money.create(50, EUR);

    expect(() => money1.add(money2)).toThrow("Cannot add money with different currencies");
  });

  it("should equal another money with same amount and currency", () => {
    const money1 = Money.create(100, USD);
    const money2 = Money.create(100, USD);
    expect(money1.equals(money2)).toBe(true);
  });

  it("should not equal another money with different amount", () => {
    const money1 = Money.create(100, USD);
    const money2 = Money.create(50, USD);
    expect(money1.equals(money2)).toBe(false);
  });

  it("should not equal another money with different currency", () => {
    const money1 = Money.create(100, USD);
    const money2 = Money.create(100, EUR);
    expect(money1.equals(money2)).toBe(false);
  });

  it("should format money as string", () => {
    const money = Money.create(123.456, USD);
    expect(money.toString()).toBe("$123.46");
  });
});
```

This implementation follows Clean Architecture principles:

1. **Pure Value Object**: The `Money` class is immutable and represents a value with no identity
2. **No External Dependencies**: The class doesn't depend on any external libraries or frameworks
3. **Currency Enforcement**: Uses a dedicated `Currency` interface to define currency properties
4. **Positive Value Enforcement**: Throws an error when attempting to create negative amounts
5. **Currency Validation**: The `add` method validates that both operands have the same currency
6. **Type Safety**: Uses strict typing with interfaces and avoids `any` type
7. **Immutability**: All properties are private and the class is immutable
8. **Result Pattern**: While not explicitly required, the error handling follows the pattern of throwing exceptions for invalid states (which is the idiomatic way in TypeScript for such cases)

The implementation is fully testable and demonstrates proper domain-driven design principles with clear separation of concerns.

