export interface PaymentError {
  code: string;
  message: string;
}

export interface PaymentRequest {
  amount: number;
  currency: string;
  customerId: string;
  description?: string;
}

export interface PaymentResponse {
  id: string;
  status: 'succeeded' | 'failed' | 'pending';
  amount: number;
  currency: string;
  customerId: string;
  createdAt: Date;
}

export type Result<T, E extends PaymentError> = 
  | { success: true; data: T }
  | { success: false; error: E };

// Application Layer - Use Cases
export interface IPaymentGateway {
  processPayment(request: PaymentRequest): Promise<Result<PaymentResponse, PaymentError>>;
}

// Infrastructure Layer - Adapter Implementation
export class StripePaymentAdapter implements IPaymentGateway {
  private stripe: any; // This would be injected in real implementation

  constructor(stripeApiKey: string) {
    // In a real implementation, we would inject the Stripe client
    // For this example, we'll simulate the behavior
    this.stripe = {
      charges: {
        create: this.createCharge.bind(this)
      }
    };
  }

  async processPayment(request: PaymentRequest): Promise<Result<PaymentResponse, PaymentError>> {
    try {
      // Simulate Stripe API call
      const charge = await this.stripe.charges.create({
        amount: Math.round(request.amount * 100), // Convert to cents
        currency: request.currency,
        customer: request.customerId,
        description: request.description
      });

      return {
        success: true,
        data: {
          id: charge.id,
          status: charge.status,
          amount: charge.amount / 100, // Convert back to dollars
          currency: charge.currency,
          customerId: charge.customer,
          createdAt: new Date(charge.created * 1000)
        }
      };
    } catch (error: any) {
      return {
        success: false,
        error: {
          code: error.type || 'UNKNOWN_ERROR',
          message: error.message || 'Payment processing failed'
        }
      };
    }
  }

  private async createCharge(chargeData: any): Promise<any> {
    // Simulate async operation
    return new Promise((resolve, reject) => {
      setTimeout(() => {
        if (Math.random() > 0.1) { // 90% success rate for demo
          resolve({
            id: `ch_${Math.random().toString(36).substr(2, 9)}`,
            status: 'succeeded',
            amount: chargeData.amount,
            currency: chargeData.currency,
            customer: chargeData.customer,
            created: Math.floor(Date.now() / 1000)
          });
        } else {
          reject({
            type: 'CARD_ERROR',
            message: 'Insufficient funds'
          });
        }
      }, 100);
    });
  }
}

// Usage example (Application Layer)
export class PaymentService {
  constructor(private paymentGateway: IPaymentGateway) {}

  async processCustomerPayment(request: PaymentRequest): Promise<Result<PaymentResponse, PaymentError>> {
    return await this.paymentGateway.processPayment(request);
  }
}
```

This implementation follows Clean Architecture principles:

1. **Domain Layer**:
   - Defines core interfaces (`IPaymentGateway`) and types (`PaymentRequest`, `PaymentResponse`, `PaymentError`)
   - Uses the `Result<T, E>` pattern for error handling
   - No dependencies on external libraries or frameworks

2. **Application Layer**:
   - Contains the use case (`PaymentService`) that depends on the domain interface
   - Uses the `IPaymentGateway` interface without knowing the implementation details

3. **Infrastructure Layer**:
   - Implements the `StripePaymentAdapter` that conforms to `IPaymentGateway`
   - Contains Stripe-specific logic but is isolated from domain concerns
   - Uses the same `Result<T, E>` pattern for consistent error handling

The dependency rule is enforced by:
- Domain layer only depends on itself
- Application layer depends only on domain interfaces
- Infrastructure layer depends on both domain and application layers (but not vice versa)
- No direct dependencies on external frameworks or libraries in domain/application layers

The `Result<T, E>` pattern ensures type-safe error handling throughout the system, and all types are explicitly defined with no `any` types used.

